-- Chopinz core. Money is stored in integer NGN kobo. Run via Supabase CLI migrations.
create extension if not exists pgcrypto;
create schema if not exists private;
create type public.order_state as enum ('pending_payment','paid','processing','partially_completed','completed','cancelled','partially_cancelled','refunded','partially_refunded');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, created_at timestamptz default now());
create table public.user_roles (user_id uuid references auth.users(id) on delete cascade, role text not null check(role in ('admin','support')), primary key(user_id,role));
create table public.business_categories(id uuid primary key default gen_random_uuid(), name text unique not null, active boolean default true);
create table public.businesses(id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id), category_id uuid references public.business_categories, name text not null, slug text unique not null, description text, phone text, logo_path text, cover_path text, verification_status text not null default 'pending' check(verification_status in ('pending','approved','rejected','suspended')), commission_bps integer not null default 500 check(commission_bps between 0 and 10000), created_at timestamptz default now());
create table public.business_members(business_id uuid references public.businesses on delete cascade,user_id uuid references auth.users on delete cascade,role text not null check(role in ('owner','manager','staff')),primary key(business_id,user_id));
create table public.business_locations(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,name text not null,address text not null,city text,state text,latitude numeric,longitude numeric,delivery_enabled boolean default true,pickup_enabled boolean default true,is_open boolean default true,operating_hours jsonb default '{}'::jsonb);
create table public.business_documents(id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses on delete cascade,storage_path text not null,kind text not null,status text default 'pending',created_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),parent_id uuid references public.categories,name text not null,slug text unique not null,active boolean default true);
create table public.products(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses on delete cascade,category_id uuid references public.categories,name text not null,slug text not null,description text,unit text default 'each',attributes jsonb default '{}'::jsonb,preparation_minutes integer default 0,status text default 'draft' check(status in ('draft','active','archived','suspended')),created_at timestamptz default now(),unique(business_id,slug));
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid references public.products on delete cascade,storage_path text not null,sort_order int default 0);
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,sku text,options jsonb default '{}'::jsonb,price_kobo bigint not null check(price_kobo>=0),compare_at_kobo bigint,minimum_quantity int default 1 check(minimum_quantity>0),maximum_quantity int,active boolean default true,unique(product_id,sku));
create table public.price_tiers(id uuid primary key default gen_random_uuid(),variant_id uuid references public.product_variants on delete cascade,min_quantity int not null check(min_quantity>0),unit_price_kobo bigint not null check(unit_price_kobo>=0),unique(variant_id,min_quantity));
create table public.inventory(location_id uuid references public.business_locations on delete cascade,variant_id uuid references public.product_variants on delete cascade,on_hand int not null default 0 check(on_hand>=0),reserved int not null default 0 check(reserved>=0 and reserved<=on_hand),primary key(location_id,variant_id));
create table public.inventory_movements(id bigint generated always as identity primary key,location_id uuid,variant_id uuid,delta int not null,reason text not null,reference_id uuid,actor_id uuid,created_at timestamptz default now());
create table public.customer_addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,label text,recipient text,phone text,address text not null,city text,state text,latitude numeric,longitude numeric,created_at timestamptz default now());
create table public.carts(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users on delete cascade,created_at timestamptz default now());
create table public.cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts on delete cascade,variant_id uuid not null references public.product_variants,location_id uuid not null references public.business_locations,quantity int not null check(quantity>0),unique(cart_id,variant_id,location_id));
create table public.wishlists(user_id uuid references auth.users on delete cascade,product_id uuid references public.products on delete cascade,primary key(user_id,product_id));
create table public.recently_viewed(user_id uuid references auth.users on delete cascade,product_id uuid references public.products on delete cascade,viewed_at timestamptz default now(),primary key(user_id,product_id));
create table public.promotions(id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses,code text unique,kind text check(kind in ('percent','fixed')),value bigint not null check(value>=0),starts_at timestamptz,ends_at timestamptz,usage_limit int,used_count int default 0,active boolean default false);
create table public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,reference text not null unique,status public.order_state not null default 'pending_payment',currency text not null default 'NGN',subtotal_kobo bigint not null,delivery_kobo bigint not null default 0,discount_kobo bigint not null default 0,total_kobo bigint not null,expires_at timestamptz not null default(now()+interval '15 minutes'),created_at timestamptz default now(),idempotency_key text not null,unique(user_id,idempotency_key));
create table public.seller_orders(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,business_id uuid not null references public.businesses,location_id uuid not null references public.business_locations,status text not null default 'pending' check(status in ('pending','accepted','preparing','ready_for_fulfillment','ready_for_pickup','awaiting_dispatch','out_for_delivery','delivered','completed','rejected','cancelled')),fulfillment_method text not null check(fulfillment_method in ('pickup','delivery')),address_snapshot jsonb,subtotal_kobo bigint not null,delivery_kobo bigint not null default 0,commission_kobo bigint not null default 0,pickup_code_hash text,created_at timestamptz default now(),unique(order_id,location_id));
create table public.order_items(id uuid primary key default gen_random_uuid(),seller_order_id uuid not null references public.seller_orders on delete cascade,variant_id uuid references public.product_variants,product_name text not null,variant_options jsonb not null,quantity int not null,unit_price_kobo bigint not null,line_total_kobo bigint not null);
create table public.order_status_history(id bigint generated always as identity primary key,seller_order_id uuid references public.seller_orders,order_id uuid references public.orders,old_status text,new_status text not null,actor_id uuid,created_at timestamptz default now());
create table public.delivery_providers(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,enabled boolean default false,configuration jsonb default '{}'::jsonb);
create table public.delivery_quotes(id uuid primary key default gen_random_uuid(),location_id uuid references public.business_locations,provider_id uuid references public.delivery_providers,customer_id uuid references auth.users,amount_kobo bigint not null check(amount_kobo>=0),address_id uuid references public.customer_addresses,expires_at timestamptz not null,metadata jsonb default '{}'::jsonb);
create table public.fulfillments(id uuid primary key default gen_random_uuid(),seller_order_id uuid unique references public.seller_orders,provider_id uuid references public.delivery_providers,external_reference text,tracking_url text,status text default 'pending',driver_name text,driver_phone text,updated_at timestamptz default now());
create table public.delivery_tracking_events(id bigint generated always as identity primary key,fulfillment_id uuid references public.fulfillments on delete cascade,status text not null,notes text,created_at timestamptz default now());
create table public.pickup_details(seller_order_id uuid primary key references public.seller_orders on delete cascade,ready_at timestamptz,collected_at timestamptz,confirmed_by uuid);
create table public.payment_providers(code text primary key,name text not null,enabled boolean default false,priority int default 100);
insert into public.payment_providers values ('paystack','Paystack',false,10),('flutterwave','Flutterwave',false,20) on conflict do nothing;
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders,provider text not null references public.payment_providers(code),status text not null default 'pending' check(status in ('pending','success','failed','refunded','partially_refunded')),amount_kobo bigint not null,currency text default 'NGN',created_at timestamptz default now());
create table public.payment_transactions(id uuid primary key default gen_random_uuid(),payment_id uuid references public.payments,provider_reference text not null,provider text not null,status text default 'initialized',checkout_url text,raw jsonb default '{}'::jsonb,created_at timestamptz default now(),unique(provider,provider_reference));
create table public.webhook_events(provider text not null,event_id text not null,payload jsonb not null,processed_at timestamptz default now(),primary key(provider,event_id));
create table public.commissions(seller_order_id uuid primary key references public.seller_orders,amount_kobo bigint not null,rate_bps int not null);
create table public.seller_ledger(id bigint generated always as identity primary key,business_id uuid not null references public.businesses,seller_order_id uuid references public.seller_orders,kind text not null check(kind in ('sale','commission','refund','payout','adjustment')),amount_kobo bigint not null,reference text unique not null,created_at timestamptz default now());
create table public.seller_payouts(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses,amount_kobo bigint not null check(amount_kobo>0),status text not null default 'requested',provider text,provider_reference text,approved_by uuid,created_at timestamptz default now());
create table public.refunds(id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.payments,seller_order_id uuid references public.seller_orders,amount_kobo bigint not null check(amount_kobo>0),reason text,status text default 'requested',provider_reference text,created_at timestamptz default now());
create table public.platform_settings(key text primary key,value jsonb not null,updated_at timestamptz default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,product_id uuid references public.products,business_id uuid references public.businesses,order_item_id uuid unique references public.order_items,rating int not null check(rating between 1 and 5),comment text,status text default 'pending',created_at timestamptz default now());
create table public.coupons(id uuid primary key default gen_random_uuid(),promotion_id uuid references public.promotions,code text unique not null);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users,kind text not null,title text not null,body text,read_at timestamptz,created_at timestamptz default now());
create table public.notification_jobs(id bigint generated always as identity primary key,user_id uuid references auth.users,channel text not null check(channel in ('sms','email')),template_key text,subject text,body text,variables jsonb default '{}'::jsonb,status text not null default 'pending',attempts int not null default 0,next_attempt_at timestamptz default now(),last_error text,created_at timestamptz default now());
create table public.support_tickets(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users,business_id uuid references public.businesses,subject text not null,description text,status text default 'open',created_at timestamptz default now());
create table public.disputes(id uuid primary key default gen_random_uuid(),ticket_id uuid references public.support_tickets,order_id uuid references public.orders,status text default 'open',resolution text,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid,action text not null,entity text not null,entity_id uuid,details jsonb default '{}'::jsonb,created_at timestamptz default now());
create index on public.products(business_id,status);create index on public.seller_orders(business_id,status);create index on public.orders(user_id,created_at desc);create index on public.notification_jobs(status,next_attempt_at);
-- Prevent anonymous and authenticated clients from reading or writing internal tables directly.
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t.tablename); end loop; end $$;
create policy profiles_self on public.profiles for all to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy addresses_self on public.customer_addresses for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy carts_self on public.carts for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy cart_items_self on public.cart_items for all to authenticated using(exists(select 1 from public.carts c where c.id=cart_id and c.user_id=auth.uid())) with check(exists(select 1 from public.carts c where c.id=cart_id and c.user_id=auth.uid()));
create policy wishlist_self on public.wishlists for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy viewed_self on public.recently_viewed for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy notifications_self on public.notifications for select to authenticated using(user_id=auth.uid());
create policy public_categories on public.categories for select to anon,authenticated using(active);
create policy public_business_categories on public.business_categories for select to anon,authenticated using(active);
create policy public_businesses on public.businesses for select to anon,authenticated using(verification_status='approved');
create policy public_locations on public.business_locations for select to anon,authenticated using(exists(select 1 from public.businesses b where b.id=business_id and b.verification_status='approved'));
create policy public_products on public.products for select to anon,authenticated using(status='active' and exists(select 1 from public.businesses b where b.id=business_id and b.verification_status='approved'));
create policy public_variants on public.product_variants for select to anon,authenticated using(active and exists(select 1 from public.products p join public.businesses b on b.id=p.business_id where p.id=product_id and p.status='active' and b.verification_status='approved'));
create policy public_images on public.product_images for select to anon,authenticated using(exists(select 1 from public.products p join public.businesses b on b.id=p.business_id where p.id=product_id and p.status='active' and b.verification_status='approved'));
create policy public_tiers on public.price_tiers for select to anon,authenticated using(exists(select 1 from public.product_variants v join public.products p on p.id=v.product_id join public.businesses b on b.id=p.business_id where v.id=variant_id and p.status='active' and b.verification_status='approved'));
create policy orders_self on public.orders for select to authenticated using(user_id=auth.uid());
create policy seller_orders_customer on public.seller_orders for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy order_items_customer on public.order_items for select to authenticated using(exists(select 1 from public.seller_orders so join public.orders o on o.id=so.order_id where so.id=seller_order_id and o.user_id=auth.uid()));
create policy history_customer on public.order_status_history for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy reviews_public on public.reviews for select to anon,authenticated using(status='approved');
-- Internal money tables intentionally have no client-facing RLS policies.
create or replace function public.on_auth_user_created() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name') on conflict do nothing;return new;end $$;
create trigger auth_user_created after insert on auth.users for each row execute function public.on_auth_user_created();
create or replace function private.is_admin(uid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles where user_id=uid and role='admin')$$;
create or replace function private.is_member(uid uuid,bid uuid,allowed text[]) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.business_members where user_id=uid and business_id=bid and role=any(allowed))$$;
